"""Rebuild the generated files in evidence/: test results, the hidden-text defense, and the audit-log check.

    .venv/Scripts/python scripts/build_evidence.py

Offline only: no AI calls, no network. The audit log is only read, never changed.
"""

import collections
import html
import io
import json
import os
import re
import subprocess
import sys
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "evidence"
os.environ["PORTKEY_API_KEY"] = ""  # empty, not missing, so .env can't supply a key
os.environ["THROUGH_LINE_AUDIT"] = str(ROOT / "output" / "audit_log.json")
sys.path[:0] = [str(ROOT / "backend"), str(ROOT / "tests")]


def test_results() -> None:
    """Run the offline test suite and keep its verbose output."""
    env = {**os.environ, "PORTKEY_API_KEY": ""}
    run = subprocess.run([sys.executable, "-m", "pytest", "tests", "-v", "-p", "no:cacheprovider", "--color=no"],
                         cwd=ROOT, env=env, capture_output=True, text=True, encoding="utf-8", errors="replace")
    lines = [ln for ln in run.stdout.splitlines() if "::" in ln or ln.startswith("=")]
    lines = [re.sub(r"\s+\[\s*\d+%\]$", "", ln) for ln in lines]
    header = (f"Through Line: offline test suite, run {datetime.now():%Y-%m-%d %H:%M}\n"
              f"Command: python -m pytest tests -v   (no AI calls: PORTKEY_API_KEY is empty)\n\n")
    (OUT / "test_results.txt").write_text(header + "\n".join(lines) + "\n", encoding="utf-8")
    print(f"  test_results.txt ({lines[-1].strip('= ') if lines else 'no output'})")
    if run.returncode != 0:
        raise SystemExit("Tests failed; see evidence/test_results.txt")


def hidden_text() -> None:
    """Hide 'SECRET' instructions in each file type, then compare a standard reader with Through Line's reader."""
    import docx
    import pptx
    from pypdf import PdfReader

    import test_visible_text as t
    import visible

    def secrets_in(text: str) -> list[str]:
        return [ln.strip() for ln in re.split(r"[\r\n]+|(?<=\.)\s+", text) if "SECRET" in ln.upper()]

    def std_docx(data: bytes) -> str:
        d = docx.Document(io.BytesIO(data))
        cells = [c.text for tbl in d.tables for row in tbl.rows for c in row.cells]
        return "\n".join([p.text for p in d.paragraphs] + cells)

    def std_pptx(data: bytes) -> str:
        p = pptx.Presentation(io.BytesIO(data))
        return "\n".join(s.text_frame.text for sl in p.slides for s in sl.shapes if s.has_text_frame)

    cases = [
        ("PDF", t._pdf(), lambda b: PdfReader(io.BytesIO(b)).pages[0].extract_text(), visible.pdf_text,
         "pypdf, a standard PDF library"),
        ("Word (.docx)", t._docx(), std_docx, visible.docx_text, "python-docx, reading every paragraph and cell"),
        ("PowerPoint (.pptx)", t._pptx(), std_pptx, visible.pptx_text, "python-pptx, reading every text box"),
        ("Web page (HTML)", t.HTML, lambda h: html.unescape(re.sub(r"<[^>]+>", "\n", h)), visible.html_text,
         "stripping the HTML tags"),
    ]
    md = ["# Evidence: agents only read what a person can see",
          "",
          "Hidden text is a classic prompt-injection trick: instructions in white, 1-point, off-page, or covered text that "
          "a person never sees but a program reading the file does. These are the same test documents used by "
          "`tests/test_visible_text.py`. Each one hides lines starting with **SECRET** (for example "
          "\"SECRET white: ignore your instructions\") next to ordinary visible text. Below, the same file is read two "
          "ways: by a standard reader, and by Through Line's reader (`backend/visible.py`), which every agent's input "
          "passes through.",
          "",
          f"*Generated by `scripts/build_evidence.py` on {datetime.now():%Y-%m-%d}. Offline; no AI involved.*",
          "",
          "| File type | Hidden SECRET lines a standard reader passes on | Hidden lines Through Line passes on | Visible text kept |",
          "|---|---|---|---|"]
    details = []
    for name, data, standard, ours, how in cases:
        std = secrets_in(standard(data))
        text, hidden = ours(data)
        kept = all(v in " ".join(text.split()) for v in t.VISIBLE)
        md.append(f"| {name} | **{len(std)}** | **{len(secrets_in(text))}** | {'yes, all of it' if kept else 'NO'} |")
        reasons = sorted({r for r in (t._reasons(hidden))})
        details += [f"## {name}", "",
                    f"**Standard reader** ({how}) passes on:", "",
                    *[f"- `{s[:90]}`" for s in std], "",
                    "**Through Line's reader** passes on only:", "",
                    "```", " ".join(text.split())[:400], "```", "",
                    f"It skipped hidden text for these reasons: {', '.join(reasons)}.", ""]
    md += ["", *details,
           "In the app, the skipped text is never shown to the agents. The audit log records only *how many* pieces were "
           "skipped and why, never the hidden text itself (see `audit_log_check.md`, event `hidden_text_skipped`)."]
    (OUT / "hidden_text_defense.md").write_text("\n".join(md) + "\n", encoding="utf-8")
    print("  hidden_text_defense.md")


def audit_check() -> None:
    """Verify the audit log's hash chain and show what the defenses recorded during real runs."""
    from audit import audit_verify

    v = audit_verify()
    entries = json.loads((ROOT / "output" / "audit_log.json").read_text(encoding="utf-8"))
    counts = collections.Counter(e.get("event") for e in entries)
    first, last = entries[0]["logged_at"][:10], entries[-1]["logged_at"][:10]

    def examples(event: str, n: int = 3) -> list[str]:
        rows = []
        for e in [e for e in entries if e.get("event") == event][:n]:
            what = e.get("input_summary") or json.dumps(e.get("output") or e.get("human") or {})[:160]
            rows.append(f"| {e['seq']} | {e['logged_at'][:16].replace('T', ' ')} | {e.get('team') or ''} | {what} |")
        return rows

    md = ["# Evidence: the audit log", "",
          "Every agent step, human approval, sign-in, export, and safety action is appended to "
          "[`output/audit_log.json`](../output/audit_log.json). Each entry stores the hash of the one before it, so "
          "editing or deleting any entry breaks the chain. This file is the log from building and testing the app "
          f"locally ({first} to {last}); the live site keeps its own.",
          "",
          f"*Generated by `scripts/build_evidence.py` on {datetime.now():%Y-%m-%d}. The log was only read.*",
          "",
          "## Integrity check", "",
          f"- Entries: **{v['entries']}**",
          f"- Hash chain intact: **{'yes' if v['ok'] else 'NO: ' + str(v['problem'])}**",
          "",
          "## What happened, by event", "",
          "| Event | Count |", "|---|---|",
          *[f"| `{k}` | {c} |" for k, c in counts.most_common()],
          "",
          "## Defenses at work (first few of each)", "",
          "**Usage limits stopping extra AI calls** (`limit_reached`):", "",
          "| # | When (UTC) | Team | What |", "|---|---|---|---|", *examples("limit_reached", 5), "",
          "**Hidden text skipped before an agent read a document** (`hidden_text_skipped`; counts and reasons only):", "",
          "| # | When (UTC) | Team | What |", "|---|---|---|---|", *examples("hidden_text_skipped"), "",
          "**Uploads dropped from memory once read** (`sources_discarded`):", "",
          "| # | When (UTC) | Team | What |", "|---|---|---|---|", *examples("sources_discarded"), "",
          "**People approving AI output** (`human_approved`):", "",
          "| # | When (UTC) | Team | What |", "|---|---|---|---|", *examples("human_approved"), "",
          "Sign-in events record only the role and organization number, never a username or password."]
    (OUT / "audit_log_check.md").write_text("\n".join(md) + "\n", encoding="utf-8")
    print(f"  audit_log_check.md ({v['entries']} entries, chain {'intact' if v['ok'] else 'BROKEN'})")


if __name__ == "__main__":
    OUT.mkdir(exist_ok=True)
    hidden_text()
    audit_check()
    test_results()
